import 'package:bones_ui/bones_ui_kit.dart';
import 'package:bones_ui_bootstrap/bones_ui_bootstrap.dart';

class MyUI extends UIRoot {
  MyUI(super.rootContainer);
  @override
  void configure() => Bootstrap.load();
  @override
  UIComponent renderContent() => $div(classes:'container',content:'Hello Bootstrap');
}

void main(){
  var out=document.querySelector('#output');
  MyUI(out).initialize();
}
